{"gameType":"arcade-run","input":"tap-anywhere","lang":"fr","loop":"L'escargot avance tout seul sur la piste, tape l'écran pour sauter les obstacles et ramasser les feuilles. Une collision termine la course et affiche le score final.","slug":"course-d-escargots","style":"risograph","title":"Course d'Escargots"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Course d'Escargots</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0;
10|     width: 100%; height: 100%;
11|     background: #fbf7ee;
12|     overflow: hidden;
13|     font-family: 'Arial Narrow', Arial, sans-serif;
14|   }
15|   canvas {
16|     display: block;
17|     touch-action: none;
18|     background: #fbf7ee;
19|   }
20| </style>
21| </head>
22| <body>
23| <canvas id="game"></canvas>
24| <script>
25| // ---------- Bridge helper (verbatim) ----------
26| const CARTRIDGE = {
27|   send(type, payload = {}) {
28|     window.parent.postMessage(
29|       { source: "cartridge", v: 1, type, payload },
30|       "*",
31|     );
32|   },
33| };
34| 
35| // ---------- Setup ----------
36| const canvas = document.getElementById("game");
37| const ctx = canvas.getContext("2d");
38| canvas.style.touchAction = "none";
39| 
40| let W = 0, H = 0, DPR = 1;
41| function resize() {
42|   DPR = window.devicePixelRatio || 1;
43|   W = window.innerWidth;
44|   H = window.innerHeight;
45|   canvas.width = Math.floor(W * DPR);
46|   canvas.height = Math.floor(H * DPR);
47|   canvas.style.width = W + "px";
48|   canvas.style.height = H + "px";
49|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
50|   buildGrain();
51| }
52| window.addEventListener("resize", resize);
53| 
54| // ---------- Risograph palette ----------
55| const PAPER = "#fbf7ee";
56| const INK1 = "#ff48b0";
57| const INK2 = "#0078bf";
58| const OVERLAP = "#5b3a8c";
59| 
60| // ---------- Grain tile (pre-rendered) ----------
61| let grainCanvas = null;
62| function buildGrain() {
63|   const size = 128;
64|   grainCanvas = document.createElement("canvas");
65|   grainCanvas.width = size;
66|   grainCanvas.height = size;
67|   const gctx = grainCanvas.getContext("2d");
68|   const imgData = gctx.createImageData(size, size);
69|   for (let i = 0; i < imgData.data.length; i += 4) {
70|     const v = Math.random() * 255;
71|     imgData.data[i] = v;
72|     imgData.data[i + 1] = v;
73|     imgData.data[i + 2] = v;
74|     imgData.data[i + 3] = 255;
75|   }
76|   gctx.putImageData(imgData, 0, 0);
77| }
78| 
79| function drawGrain() {
80|   if (!grainCanvas) return;
81|   ctx.save();
82|   ctx.globalAlpha = 0.08;
83|   const pattern = ctx.createPattern(grainCanvas, "repeat");
84|   ctx.fillStyle = pattern;
85|   ctx.fillRect(0, 0, W, H);
86|   ctx.restore();
87| }
88| 
89| // ---------- Game state ----------
90| let last = 0;
91| let running = false;
92| let paused = false;
93| let started = false; // whether boot/start flow has begun
94| let score = 0;
95| let scoreShown = -1;
96| 
97| const GROUND_Y_FRAC = 0.75;
98| let groundY = 0;
99| 
100| let snail = {
101|   x: 0,
102|   y: 0,
103|   vy: 0,
104|   w: 56,
105|   h: 34,
106|   onGround: true,
107|   jumpForce: -620,
108| };
109| const GRAVITY = 1700;
110| 
111| let obstacles = [];
112| let leaves = [];
113| let spawnTimer = 0;
114| let leafTimer = 0;
115| let speed = 220;
116| const BASE_SPEED = 220;
117| const MAX_SPEED = 520;
118| let elapsed = 0;
119| let firstHazardSpawned = false;
120| 
121| let clouds = [];
122| function initClouds() {
123|   clouds = [];
124|   for (let i = 0; i < 5; i++) {
125|     clouds.push({
126|       x: Math.random() * 1000,
127|       y: 40 + Math.random() * 140,
128|       s: 0.6 + Math.random() * 0.8,
129|       speed: 15 + Math.random() * 15,
130|     });
131|   }
132| }
133| 
134| let tapHintPulse = 0;
135| 
136| function resetState() {
137|   score = 0;
138|   scoreShown = -1;
139|   obstacles = [];
140|   leaves = [];
141|   spawnTimer = 1.4; // opening lane clear
142|   leafTimer = 0.8;
143|   speed = BASE_SPEED;
144|   elapsed = 0;
145|   firstHazardSpawned = false;
146|   groundY = H * GROUND_Y_FRAC;
147|   snail.x = W * 0.22;
148|   snail.y = groundY - snail.h;
149|   snail.vy = 0;
150|   snail.onGround = true;
151|   initClouds();
152| }
153| 
154| function backToTitle() {
155|   running = false;
156|   paused = false;
157|   started = false;
158|   resetState();
159| }
160| 
161| // ---------- Input ----------
162| canvas.addEventListener("pointerdown", (event) => {
163|   event.preventDefault();
164|   if (paused) return;
165|   if (!started) {
166|     started = true;
167|     running = true;
168|     resetState();
169|     CARTRIDGE.send("start");
170|     return;
171|   }
172|   if (running) {
173|     act();
174|   } else {
175|     // after crash, tap restarts to title-ready state, then next tap starts
176|     backToTitle();
177|   }
178| });
179| 
180| function act() {
181|   if (snail.onGround) {
182|     snail.vy = snail.jumpForce;
183|     snail.onGround = false;
184|   }
185| }
186| 
187| // ---------- Host messages ----------
188| window.addEventListener("message", (event) => {
189|   const data = event.data;
190|   if (!data || data.source !== "cartridge-host") return;
191|   if (data.type === "pause") paused = true;
192|   if (data.type === "resume") paused = false;
193|   if (data.type === "reset") backToTitle();
194| });
195| 
196| // ---------- Spawning ----------
197| function spawnObstacle() {
198|   const size = 34 + Math.random() * 20;
199|   obstacles.push({
200|     x: W + size,
201|     y: groundY - size,
202|     w: size,
203|     h: size,
204|     passed: false,
205|   });
206|   firstHazardSpawned = true;
207| }
208| 
209| function spawnLeaf() {
210|   const y = groundY - 60 - Math.random() * 120;
211|   leaves.push({
212|     x: W + 20,
213|     y: y,
214|     r: 12,
215|     taken: false,
216|   });
217| }
218| 
219| // ---------- Update ----------
220| function advance(dt) {
221|   elapsed += dt;
222|   speed = Math.min(MAX_SPEED, BASE_SPEED + elapsed * 9);
223| 
224|   // clouds always move for liveliness
225|   for (const c of clouds) {
226|     c.x -= c.speed * dt;
227|     if (c.x < -80) c.x = W + 80;
228|   }
229| 
230|   // physics
231|   snail.vy += GRAVITY * dt;
232|   snail.y += snail.vy * dt;
233|   if (snail.y >= groundY - snail.h) {
234|     snail.y = groundY - snail.h;
235|     snail.vy = 0;
236|     snail.onGround = true;
237|   }
238| 
239|   // spawn timers
240|   spawnTimer -= dt;
241|   if (spawnTimer <= 0) {
242|     spawnObstacle();
243|     spawnTimer = Math.max(0.9, 1.9 - elapsed * 0.02) + Math.random() * 0.6;
244|   }
245|   leafTimer -= dt;
246|   if (leafTimer <= 0) {
247|     spawnLeaf();
248|     leafTimer = 1.2 + Math.random() * 1.4;
249|   }
250| 
251|   // move obstacles
252|   for (const o of obstacles) {
253|     o.x -= speed * dt;
254|     if (!o.passed && o.x + o.w < snail.x) {
255|       o.passed = true;
256|       score += 1;
257|       CARTRIDGE.send("score", { value: score });
258|     }
259|   }
260|   obstacles = obstacles.filter((o) => o.x > -60);
261| 
262|   // move leaves
263|   for (const l of leaves) {
264|     l.x -= speed * dt;
265|   }
266|   leaves = leaves.filter((l) => l.x > -40 && !l.taken);
267| }
268| 
269| function collide() {
270|   // obstacle collision
271|   const sx = snail.x + 8;
272|   const sy = snail.y + 4;
273|   const sw = snail.w - 16;
274|   const sh = snail.h - 8;
275|   for (const o of obstacles) {
276|     if (
277|       sx < o.x + o.w &&
278|       sx + sw > o.x &&
279|       sy < o.y + o.h &&
280|       sy + sh > o.y
281|     ) {
282|       crash();
283|       return;
284|     }
285|   }
286|   // leaf pickup
287|   for (const l of leaves) {
288|     const dx = (snail.x + snail.w / 2) - l.x;
289|     const dy = (snail.y + snail.h / 2) - l.y;
290|     const dist = Math.sqrt(dx * dx + dy * dy);
291|     if (dist < l.r + 20) {
292|       l.taken = true;
293|       score += 3;
294|       CARTRIDGE.send("score", { value: score });
295|     }
296|   }
297| }
298| 
299| function crash() {
300|   running = false;
301|   CARTRIDGE.send("end", { reason: "lose", value: score });
302| }
303| 
304| // ---------- Drawing ----------
305| function drawCloud(c) {
306|   ctx.save();
307|   ctx.translate(c.x, c.y);
308|   ctx.scale(c.s, c.s);
309|   ctx.fillStyle = INK2;
310|   ctx.globalAlpha = 0.5;
311|   ctx.beginPath();
312|   ctx.arc(0, 0, 22, 0, Math.PI * 2);
313|   ctx.arc(24, -6, 16, 0, Math.PI * 2);
314|   ctx.arc(-22, -4, 14, 0, Math.PI * 2);
315|   ctx.fill();
316|   ctx.restore();
317|   ctx.globalAlpha = 1;
318| }
319| 
320| function drawGround() {
321|   // ground band ink2
322|   ctx.fillStyle = INK2;
323|   ctx.fillRect(0, groundY, W, H - groundY);
324|   // misregistered offset strip ink1
325|   ctx.fillStyle = INK1;
326|   ctx.globalAlpha = 0.85;
327|   ctx.fillRect(0, groundY + 2, W, 6);
328|   ctx.globalAlpha = 1;
329|   // dashes for motion
330|   ctx.fillStyle = PAPER;
331|   const dashW = 30, gap = 26;
332|   const offset = (elapsed * speed) % (dashW + gap);
333|   for (let x = -offset; x < W; x += dashW + gap) {
334|     ctx.fillRect(x, groundY + H * 0.06, dashW, 4);
335|   }
336| }
337| 
338| function drawSnail() {
339|   const x = snail.x, y = snail.y;
340|   ctx.save();
341|   ctx.translate(x, y);
342| 
343|   // shell (ink1) with slight offset ink2 outline for misregistration
344|   ctx.fillStyle = INK2;
345|   ctx.beginPath();
346|   ctx.arc(18, 12, 17, 0, Math.PI * 2);
347|   ctx.fill();
348| 
349|   ctx.fillStyle = INK1;
350|   ctx.beginPath();
351|   ctx.arc(16, 10, 16, 0, Math.PI * 2);
352|   ctx.fill();
353| 
354|   // shell spiral (overlap color)
355|   ctx.strokeStyle = OVERLAP;
356|   ctx.lineWidth = 2;
357|   ctx.beginPath();
358|   ctx.arc(16, 10, 9, 0, Math.PI * 1.5);
359|   ctx.stroke();
360| 
361|   // body (ink2)
362|   ctx.fillStyle = INK2;
363|   ctx.beginPath();
364|   ctx.moveTo(0, snail.h);
365|   ctx.quadraticCurveTo(-4, snail.h - 14, 10, snail.h - 18);
366|   ctx.quadraticCurveTo(30, snail.h - 22, 46, snail.h - 6);
367|   ctx.quadraticCurveTo(50, snail.h, 44, snail.h);
368|   ctx.lineTo(0, snail.h);
369|   ctx.fill();
370| 
371|   // eye stalks
372|   ctx.strokeStyle = INK2;
373|   ctx.lineWidth = 3;
374|   ctx.beginPath();
375|   ctx.moveTo(42, snail.h - 10);
376|   ctx.lineTo(50, snail.h - 22);
377|   ctx.stroke();
378|   ctx.fillStyle = OVERLAP;
379|   ctx.beginPath();
380|   ctx.arc(50, snail.h - 22, 3, 0, Math.PI * 2);
381|   ctx.fill();
382| 
383|   ctx.restore();
384| }
385| 
386| function drawObstacle(o) {
387|   ctx.save();
388|   ctx.translate(o.x, o.y);
389|   // rock shape, ink2 base, ink1 offset top for misregistration
390|   ctx.fillStyle = INK2;
391|   ctx.beginPath();
392|   ctx.moveTo(0, o.h);
393|   ctx.lineTo(o.w * 0.15, o.h * 0.2);
394|   ctx.lineTo(o.w * 0.55, 0);
395|   ctx.lineTo(o.w, o.h * 0.35);
396|   ctx.lineTo(o.w * 0.9, o.h);
397|   ctx.closePath();
398|   ctx.fill();
399| 
400|   ctx.fillStyle = INK1;
401|   ctx.globalAlpha = 0.7;
402|   ctx.beginPath();
403|   ctx.moveTo(2, o.h - 2);
404|   ctx.lineTo(o.w * 0.15 + 2, o.h * 0.2 - 2);
405|   ctx.lineTo(o.w * 0.55 + 2, -2);
406|   ctx.lineTo(o.w + 2, o.h * 0.35 - 2);
407|   ctx.lineTo(o.w * 0.9 + 2, o.h - 2);
408|   ctx.closePath();
409|   ctx.fill();
410|   ctx.globalAlpha = 1;
411| 
412|   ctx.restore();
413| }
414| 
415| function drawLeaf(l) {
416|   ctx.save();
417|   ctx.translate(l.x, l.y);
418|   ctx.fillStyle = INK1;
419|   ctx.beginPath();
420|   ctx.ellipse(0, 0, l.r, l.r * 0.6, Math.PI / 4, 0, Math.PI * 2);
421|   ctx.fill();
422|   ctx.fillStyle = OVERLAP;
423|   ctx.globalAlpha = 0.6;
424|   ctx.beginPath();
425|   ctx.ellipse(1, 1, l.r, l.r * 0.6, Math.PI / 4, 0, Math.PI * 2);
426|   ctx.fill();
427|   ctx.globalAlpha = 1;
428|   ctx.restore();
429| }
430| 
431| function drawScore() {
432|   ctx.fillStyle = OVERLAP;
433|   ctx.font = "bold 28px Arial Narrow, Arial, sans-serif";
434|   ctx.textAlign = "left";
435|   ctx.textBaseline = "top";
436|   ctx.fillText("Score: " + score, 16, 16);
437| }
438| 
439| function drawTitleScreen() {
440|   ctx.fillStyle = PAPER;
441|   ctx.fillRect(0, 0, W, H);
442| 
443|   for (const c of clouds) drawCloud(c);
444|   drawGround();
445|   drawSnail();
446| 
447|   ctx.fillStyle = OVERLAP;
448|   ctx.textAlign = "center";
449|   ctx.font = "bold 40px Arial Narrow, Arial, sans-serif";
450|   ctx.fillText("Course d'Escargots", W / 2, H * 0.25);
451| 
452|   tapHintPulse += 0.05;
453|   const alpha = 0.6 + 0.4 * Math.sin(tapHintPulse);
454|   ctx.globalAlpha = alpha;
455|   ctx.fillStyle = INK1;
456|   ctx.font = "bold 26px Arial Narrow, Arial, sans-serif";
457|   ctx.fillText("Touchez pour commencer", W / 2, H * 0.4);
458|   ctx.globalAlpha = 1;
459| 
460|   drawGrain();
461| }
462| 
463| function drawGameOver() {
464|   ctx.fillStyle = PAPER;
465|   ctx.fillRect(0, 0, W, H);
466|   for (const c of clouds) drawCloud(c);
467|   drawGround();
468|   for (const o of obstacles) drawObstacle(o);
469|   for (const l of leaves) if (!l.taken) drawLeaf(l);
470|   drawSnail();
471| 
472|   ctx.fillStyle = "rgba(251,247,238,0.85)";
473|   ctx.fillRect(0, H * 0.28, W, H * 0.3);
474| 
475|   ctx.fillStyle = OVERLAP;
476|   ctx.textAlign = "center";
477|   ctx.font = "bold 38px Arial Narrow, Arial, sans-serif";
478|   ctx.fillText("Course terminée !", W / 2, H * 0.35);
479| 
480|   ctx.font = "bold 28px Arial Narrow, Arial, sans-serif";
481|   ctx.fillStyle = INK2;
482|   ctx.fillText("Score final: " + score, W / 2, H * 0.42);
483| 
484|   tapHintPulse += 0.05;
485|   const alpha = 0.6 + 0.4 * Math.sin(tapHintPulse);
486|   ctx.globalAlpha = alpha;
487|   ctx.fillStyle = INK1;
488|   ctx.font = "bold 22px Arial Narrow, Arial, sans-serif";
489|   ctx.fillText("Touchez pour revenir au titre", W / 2, H * 0.5);
490|   ctx.globalAlpha = 1;
491| 
492|   drawGrain();
493| }
494| 
495| function drawGameplay() {
496|   ctx.fillStyle = PAPER;
497|   ctx.fillRect(0, 0, W, H);
498| 
499|   for (const c of clouds) drawCloud(c);
500|   drawGround();
501|   for (const o of obstacles) drawObstacle(o);
502|   for (const l of leaves) if (!l.taken) drawLeaf(l);
503|   drawSnail();
504|   drawScore();
505| 
506|   if (paused) {
507|     ctx.fillStyle = "rgba(91,58,140,0.5)";
508|     ctx.fillRect(0, 0, W, H);
509|     ctx.fillStyle = PAPER;
510|     ctx.textAlign = "center";
511|     ctx.font = "bold 32px Arial Narrow, Arial, sans-serif";
512|     ctx.fillText("Pause", W / 2, H / 2);
513|   }
514| 
515|   drawGrain();
516| }
517| 
518| function draw() {
519|   if (!started) {
520|     drawTitleScreen();
521|   } else if (running) {
522|     drawGameplay();
523|   } else {
524|     drawGameOver();
525|   }
526| }
527| 
528| // ---------- Main loop ----------
529| let booted = false;
530| function frame(now) {
531|   const dt = Math.min((now - last) / 1000, 0.05);
532|   last = now;
533|   if (running && !paused) {
534|     advance(dt);
535|     collide();
536|   }
537|   draw();
538|   if (!booted) {
539|     booted = true;
540|     CARTRIDGE.send("boot", {
541|       title: "Course d'Escargots",
542|       gameType: "arcade-run",
543|       lang: "fr",
544|     });
545|   }
546|   requestAnimationFrame(frame);
547| }
548| 
549| resize();
550| resetState();
551| requestAnimationFrame(frame);
552| </script>
553| </body>
554| </html>
555|

